-- مختبرات العلوم (4 من 6): تجارب مختبر الكيمياء من الخطط الفصلية التي أرسلها المحضر (1447هـ)،
-- كما وردت: الفصل، والتجربة ونوعها، وصفحة الكتاب ودليل التجارب، والأدوات. يُنفَّذ بعد الجزء 1. تكرار التنفيذ آمن.
on conflict (course, no) do update set chapter = excluded.chapter, chapter_title = excluded.chapter_title, title = excluded.title,
  kind = excluded.kind, guide = excluded.guide, page = excluded.page, guide_page = excluded.guide_page, tools = excluded.tools;
